tool_input.command:
cat > forgemyspec-board.yaml <<'EOF'
- id: R1
  status: doing
  title: "Mini x86 OS (bootloader + kernel, VGA text, QEMU)"
  quote: "Build a simple operating system in the current directory: x86 bare-metal, minimalist resources, bootloader + kernel with VGA text output, no external libraries, runnable in QEMU."
  steps:
    - {do: "Spec written and linted", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec lint forgemyspec-bundle/mini-os/spec.yaml --formal"}
    - {do: "User approves the spec (code UZED7E)", ok: false}
    - {do: "Implement boot sector, kernel, Makefile, tests"}
    - {do: "Gate passes", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec gate forgemyspec-bundle/mini-os"}
  next: "waiting for the user to type the approval code"
EOF
PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec board start R1; PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec board verify R1 >/dev/null 2>&1; PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec board
